+        color: var(--text);
+        font-weight: 700;
+      }
+
+      .required {
+        color: var(--danger);
+        font-weight: 800;
+      }
+
+      .helper-text,
+      .error-message,
+      .status-message {
+        margin: 0;
+        font-size: 0.95rem;
+      }
+
+      .helper-text {
+        color: var(--muted);
+      }
+
+      .error-message {
+        color: var(--danger);
+        font-weight: 700;
+      }
+
+      .error-message[hidden] {
+        display: none;
+      }
+
+      .status-message {
+        min-height: 1.45em;
+        color: var(--success);
+        font-weight: 700;
+      }
+
