<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Terms Consent Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: #111827;
        --panel-elevated: #172033;
        --text: #f8fafc;
        --muted: #cbd5e1;
        --border: #334155;
        --accent: #7c3aed;
        --accent-strong: #a78bfa;
        --danger: #fca5a5;
        --success: #86efac;
        --focus: #fbbf24;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        background:
          radial-gradient(circle at top left, rgba(124, 58, 237, 0.28), transparent 34rem),
          radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 30rem),
          var(--bg);
        color: var(--text);
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      a {
        color: var(--accent-strong);
      }

      a:hover {
        color: #ddd6fe;
      }

      a:focus-visible,
      button:focus-visible,
      input:focus-visible {
        outline: 3px solid var(--focus);
        outline-offset: 3px;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--text);
        color: var(--bg);
        padding: 0.65rem 1rem;
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .consent-card {
        width: min(100%, 32rem);
        border: 1px solid rgba(148, 163, 184, 0.24);
        border-radius: 1.5rem;
        background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.92));
        box-shadow: 0 1.5rem 4rem rgba(0, 0, 0, 0.38);
        padding: clamp(1.5rem, 5vw, 2.5rem);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent-strong);
        font-size: 0.8rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3rem);
        line-height: 1.05;
      }

      .intro {
        margin: 1rem 0 2rem;
        color: var(--muted);
      }

      .form-field {
        display: grid;
        gap: 0.75rem;
        margin-block-end: 1.5rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: var(--panel-elevated);
        padding: 1rem;
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.8rem;
        align-items: start;
      }

      input[type="checkbox"] {
        width: 1.35rem;
        height: 1.35rem;
        margin: 0.12rem 0 0;
        accent-color: var(--accent);
        cursor: pointer;
      }

      label {
        color: var(--text);
        font-weight: 700;
      }

      .required {
        color: var(--danger);
        font-weight: 800;
      }

      .helper-text,
      .error-message,
      .status-message {
        margin: 0;
        font-size: 0.95rem;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-message {
        color: var(--danger);
        font-weight: 700;
      }

      .error-message[hidden] {
        display: none;
      }

      .status-message {
        min-height: 1.45em;
        color: var(--success);
        font-weight: 700;
      }

      button {
        width: 100%;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent), #4f46e5);
        color: white;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        padding: 0.9rem 1.25rem;
        transition: transform 160ms ease, box-shadow 160ms ease;
      }

      button:hover {
        box-shadow: 0 1rem 2rem rgba(79, 70, 229, 0.32);
        transform: translateY(-1px);
      }

      button:active {
        transform: translateY(0);
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        .consent-card,
        .form-field,
        button,
        .skip-link {
          border: 1px solid CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content" class="page-shell">
      <section class="consent-card" aria-labelledby="form-title">
        <p class="eyebrow">Account setup</p>
        <h1 id="form-title">Review and agree</h1>
        <p class="intro">Confirm that you accept the terms before continuing.</p>

        <div id="app"></div>
      </section>
    </main>

    <script>
      const ConsentCheckbox = () => `
        <div class="form-field">
          <div class="checkbox-row">
            <input
              id="agree-terms"
              name="agreeTerms"
              type="checkbox"
              required
              aria-describedby="agree-terms-help agree-terms-error"
            >
            <label for="agree-terms">
              I agree to the <a href="/terms">terms of use</a>
              <span class="required" aria-hidden="true">*</span>
            </label>
          </div>
          <p id="agree-terms-help" class="helper-text">Required to create and use your account.</p>
          <p id="agree-terms-error" class="error-message" hidden>Error: You must agree to the terms of use before continuing.</p>
        </div>
      `;

      const ConsentForm = () => `
        <form id="consent-form" novalidate>
          ${ConsentCheckbox()}
          <button type="submit">Continue</button>
          <p id="form-status" class="status-message" aria-live="polite"></p>
        </form>
      `;

      document.querySelector("#app").innerHTML = ConsentForm();

      const form = document.querySelector("#consent-form");
      const checkbox = document.querySelector("#agree-terms");
      const error = document.querySelector("#agree-terms-error");
      const status = document.querySelector("#form-status");

      const setCheckboxError = (hasError) => {
        checkbox.setAttribute("aria-invalid", String(hasError));
        error.hidden = !hasError;
      };

      checkbox.addEventListener("change", () => {
        if (checkbox.checked) {
          setCheckboxError(false);
          status.textContent = "";
        }
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!checkbox.checked) {
          setCheckboxError(true);
          status.textContent = "";
          checkbox.focus();
          return;
        }

        setCheckboxError(false);
        status.textContent = "Thanks. Your consent has been recorded.";
      });
    </script>
  </body>
</html>
